  "claims": [
    {
      "claim": "The query is glipizide, a sulfonylurea sharing the N-cyclohexylsulfonylurea and phenethyl linker with glyburide (L6 M03) and related to glimepiride (L6 M02) and tolbutamide (L6 M01); glyburide is the closest transferable experimental reference.",
      "card_ids": ["C258", "C236", "C246"]
    },
    {
      "claim": "L4 glyburide Caco-2 absorptive permeability (Papp 18.1 ± 0.8 ×10^-6 cm/s) and passive permeability (19.0 ± 2.6 ×10^-6 cm/s) support efficient intestinal absorption for this chemotype despite ionization.",
      "card_ids": ["C170", "C211"]
    },
    {
      "claim": "L3 oral-exposure records for sulfonylureas show substantial systemic AUC/Cmax after oral dosing (glyburide AUCss 525.7 ng·h/mL; glimepiride AUC0-∞ 1215 ng·h/mL; gliclazide AUC0-∞ 56.32 µg·h/mL), consistent with F≥20%.",
      "card_ids": ["C97", "C108", "C81"]
    },
    {
      "claim": "L5 shows glyburide is a Pgp/BCRP/OATP2B1 substrate with efflux ratios 2.65–4, but in vivo jejunal efflux after IV is only 0.02–0.03% of dose in 60 min, so gut-wall efflux is not threshold-relevant.",
      "card_ids": ["C190", "C199", "C211", "C185"]
    },
    {
      "claim": "L6 hepatic metabolism: glimepiride shows <5% turnover in liver microsomes and low hepatic clearance (2.1 L/h/1.73 m²); tolbutamide shows low CYP2C9 intrinsic clearance; glyburide shows higher HLM CLint (52.9–67.2 µL/min/mg) and fast CYP3A4 turnover, but these are intrinsic in vitro values without unbound-fraction/scaling and do not affirm F<20%.",
      "card_ids": ["C236", "C255", "C243", "C246", "C254", "C258", "C267", "C233", "C269"]
    },
    {
      "claim": "No direct absolute F measurement for glipizide or a close sulfonylurea is supplied; the high prediction rests on transferable permeability, solubility, oral exposure, efflux, and metabolic evidence, so confidence remains moderate.",
      "card_ids": ["C170", "C97", "C185", "C258"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C236", "C255", "C243", "C246", "C254", "C258", "C267", "C233", "C269", "C251", "C240"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for glipizide or any sulfonylurea is supplied; F is inferred from permeability, solubility, oral exposure, efflux, and hepatic metabolism.",
    "No matched oral-versus-IV comparison for glipizide or a close sulfonylurea analog is supplied.",
    "No glipizide-specific Caco-2, solubility, dissolution, transporter, or hepatic metabolism data are supplied; transfer from glyburide/glimepiride/tolbutamide is based on the shared sulfonylurea core, but the benzamide/pyrazinecarboxamide difference could alter metabolism and transporter affinity.",
    "L6 hepatic intrinsic clearance values for glyburide are not accompanied by unbound fraction or in vivo scaling, so their impact on F is uncertain.",
    "Condition match is imperfect: the query has no reported external condition, while some training contexts are fed/fasted/cirrhosis; L3-L6 records are mostly healthy/fasted/fed and may not capture disease effects.",
    "No ChEMBL evidence was provided; the physicochemical prior is uncertain and not used as endpoint proof."
  ],
  "decision_summary": "Predicted high because the query is a glipizide-like sulfonylurea; L4 shows high Caco-2 permeability and adequate intestinal-fluid solubility/dissolution for glyburide, L3 shows substantial oral exposure for the sulfonylurea class, L5 shows gut-wall efflux is modest and in vivo jejunal secretion is small, and L6 hepatic intrinsic clearance values do not affirm F<20% (glimepiride/tolbutamide show low hepatic clearance; glyburide's high HLM CLint is not directly threshold-relevant). Confidence remains moderate because no direct F measurement for glipizide is supplied."
}

